/**
 * The new learner's tips on this device: whether they are on, what was
 * shown, and the writes that remember it (meta `tips`). Everything is local
 * and nothing here sends a request; the rules themselves are pure, in
 * `tips.ts`.
 *
 * Every write is a read-modify-write inside one transaction, so two screens
 * marking a tip at once cannot lose a count. None of them may be called from
 * inside a live query: the write would retrigger the query that made it.
 */
import { dayIndex } from '@lexpad/core';
import { db, getMeta, setMeta } from '@/db/schema.js';
import { loadSrsView, type SrsView } from '@/features/schedule/data.js';
import { localTimeZone } from '@/lib/format.js';
import { afterShown, freshTips, type TipId, type TipState } from './tips.js';

/**
 * The `srs_v2` feature these tips ship behind. On by default wherever SRS v2
 * is on: the server switches it off by sending `learnTips: false` (for a
 * holdout, say), and a server that has never heard of it leaves it on. Every
 * other feature reads a missing switch as off; this one is a set of hints
 * about features that are already on, so it follows them unless told not to.
 */
export const LEARN_FEATURE = 'learnTips';

/** Whether the new learner's journey shows here. Off: the app is exactly as it was. */
export function learnShows(view: SrsView): boolean {
  return view.enabled && view.features[LEARN_FEATURE] !== false;
}

/** What a screen needs to know about tips. */
export interface LearnView {
  /** The feature is on for this account and client. */
  on: boolean;
  /** This device's tips, or null before they are settled (or with the feature off). */
  tips: TipState | null;
}

export const LEARN_OFF: LearnView = { on: false, tips: null };

/** Reads the feature and this device's tips. With the feature off, one meta read. */
export async function loadLearn(): Promise<LearnView> {
  const srs = await loadSrsView();
  if (!learnShows(srs)) return LEARN_OFF;
  return { on: true, tips: await getMeta('tips') };
}

/** Today's local day index. */
export function localDay(now: Date = new Date()): number {
  return dayIndex(now, localTimeZone());
}

/**
 * Settles, once per device, whether this learner meets tips as a beginner:
 * one with no practice before today. Somebody signing up today, or on their
 * first day, is; anybody whose history (synced or local) has an earlier day
 * of answers is not, and never gets the beginner tips. Only called while the
 * feature is on, so the decision is made by what the learner had when tips
 * first reached them.
 */
export async function settleTips(now: Date = new Date()): Promise<void> {
  const today = localDay(now);
  await db.transaction('rw', db.meta, db.dayStats, async () => {
    if ((await getMeta('tips')) !== null) return;
    const earlier = await db.dayStats
      .where('day')
      .below(today)
      .filter((stat) => stat.reviewed > 0)
      .first();
    await setMeta('tips', freshTips(today, earlier === undefined));
  });
}

/** Reads, changes and writes the tips in one transaction; nothing before they are settled. */
async function updateTips(change: (tips: TipState) => TipState): Promise<TipState | null> {
  return db.transaction('rw', db.meta, async () => {
    const tips = await getMeta('tips');
    if (tips === null) return null;
    const next = change(tips);
    if (next !== tips) await setMeta('tips', next);
    return next;
  });
}

/** A tip was shown: it is put away for good and counted for the day. */
export async function markTipShown(id: TipId, now: Date = new Date()): Promise<void> {
  const today = localDay(now);
  await updateTips((tips) => afterShown(tips, id, today));
}

/** A practice session started; answers which one it is on this device (1 for the first). */
export async function startTipSession(): Promise<number | undefined> {
  const next = await updateTips((tips) => ({ ...tips, sessions: tips.sessions + 1 }));
  return next?.sessions;
}

/** A summary is showing; answers how many this device had shown before it. */
export async function noteSummary(): Promise<number | undefined> {
  const next = await updateTips((tips) => ({ ...tips, summaries: tips.summaries + 1 }));
  return next === null ? undefined : next.summaries - 1;
}

/** "Show tips" in Settings → Practice. */
export async function setTipsOff(off: boolean): Promise<void> {
  await updateTips((tips) => (tips.off === off ? tips : { ...tips, off }));
}

/** The welcome-back line was shown for the break that followed `lastPractised`. */
export async function markComeback(lastPractised: number): Promise<void> {
  await updateTips((tips) => (tips.comeback === lastPractised ? tips : { ...tips, comeback: lastPractised }));
}

/** The last day before `today` with an answer, newest first; undefined with none. */
export async function lastPractisedBefore(today: number): Promise<number | undefined> {
  const latest = await db.dayStats
    .where('day')
    .below(today)
    .reverse()
    .filter((stat) => stat.reviewed > 0)
    .first();
  return latest?.day;
}

/** "More options" was opened or closed on a settings page: it opens the same way next time here. */
export async function rememberMoreOptions(page: 'schedule' | 'practice', open: boolean): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    const now = (await getMeta('moreOptions')) ?? { schedule: false, practice: false };
    if (now[page] !== open) await setMeta('moreOptions', { ...now, [page]: open });
  });
}
