/**
 * Which teaching line, if any, a screen shows (the new learner's journey,
 * `reports/new-learner-journey.md` §3). Pure: the screen passes in what just
 * happened and what this device remembers, and gets back at most one tip.
 *
 * A tip is one short line, shown once, at the moment it helps. Every rule
 * that limits them is here as a named constant, with a test, so a screen
 * never decides on its own that a learner has seen enough.
 */
import type { StoredTips } from '@/db/schema.js';

/** Every tip, by id. Each one has its sentence in `en.ts` as `tip.<id>`. */
export const TIP_IDS = [
  'firstGrade',
  'firstMiss',
  'firstPracticeOnly',
  'firstReturn',
  'firstMastered',
  'firstLeech',
  'firstWeekFreeze',
] as const;

export type TipId = (typeof TIP_IDS)[number];

/**
 * Where a tip may appear. A session card (M2, M3, M8) is a moment of focus,
 * so only three short lines are allowed there; Today's is a line inside the
 * hero (M6), never a card; the rest belong to the summary (M9, M10, M12).
 */
export type TipPlace = 'card' | 'today' | 'summary';

export const TIP_PLACE: Readonly<Record<TipId, TipPlace>> = {
  firstGrade: 'card',
  firstMiss: 'card',
  firstPracticeOnly: 'card',
  firstReturn: 'today',
  firstMastered: 'summary',
  firstLeech: 'summary',
  firstWeekFreeze: 'summary',
};

/**
 * When two tips could show on one screen, the first in this list wins and
 * the other waits for a later visit. A word that keeps slipping is the most
 * pressing thing on a summary; a streak offer can wait a day.
 */
export const TIP_ORDER: readonly TipId[] = [
  'firstMiss',
  'firstPracticeOnly',
  'firstGrade',
  'firstReturn',
  'firstLeech',
  'firstMastered',
  'firstWeekFreeze',
];

/**
 * Tips that teach the very basics (M2, M3, M6, M9). A learner who already
 * had practice history when tips first reached this device never sees them:
 * nobody six months in needs to be told how to flip a card.
 */
export const BEGINNER_TIPS: ReadonlySet<TipId> = new Set<TipId>([
  'firstGrade',
  'firstMiss',
  'firstReturn',
  'firstMastered',
]);

/**
 * The only tips allowed on a beginner's first day (M2, M3): day one is add,
 * practise, come back, and nothing else is taught yet.
 */
export const FIRST_DAY_TIPS: ReadonlySet<TipId> = new Set<TipId>(['firstGrade', 'firstMiss']);

/**
 * Tips that do not count towards the daily cap. The day-2 line (M6) is the
 * moment spaced repetition makes sense, which is the product itself, not a
 * hint about it.
 */
export const UNCAPPED_TIPS: ReadonlySet<TipId> = new Set<TipId>(['firstReturn']);

/** New tips a learner may meet in one day, so tips never become a drip. */
export const MAX_NEW_TIPS_PER_DAY = 2;

/**
 * Sessions in which the line under the first flips (M2) is shown. Not
 * "once": a first session is often one card, and the line is about a habit.
 */
export const FIRST_GRADE_SESSIONS = 2;

/**
 * What this device remembers about tips (meta `tips`). The stored shape keys
 * `seen` by string so the database layer needs nothing from here.
 */
export type TipState = Omit<StoredTips, 'seen'> & { seen: Partial<Record<TipId, number>> };

/** What happened on the screen, as each tip's own condition. */
export interface TipSignals {
  /** The local day now. */
  today: number;
  /** Which tips this moment would call for; the caps decide among them. */
  wants: Partial<Record<TipId, boolean>>;
  /** For M2: which session of this device this one is (1 for the first). */
  session?: number;
}

/** New tips shown on `today`, by the state's own count. */
export function shownToday(state: TipState, today: number): number {
  return state.day === today ? state.today : 0;
}

/**
 * The one tip a place shows now, or undefined. `state` null means tips are
 * not settled on this device yet (or the feature is off), and then nothing
 * shows: a tip on a guess is worse than none.
 */
export function pickTip(place: TipPlace, signals: TipSignals, state: TipState | null): TipId | undefined {
  if (state === null || state.off) return undefined;
  for (const id of TIP_ORDER) {
    if (TIP_PLACE[id] !== place || signals.wants[id] !== true) continue;
    if (BEGINNER_TIPS.has(id) && !state.beginner) continue;
    // A beginner's first day is add, practise, come back; somebody who had
    // history before tips arrived has no first day to protect.
    if (state.beginner && signals.today <= state.firstDay && !FIRST_DAY_TIPS.has(id)) continue;
    const isNew = state.seen[id] === undefined;
    if (id === 'firstGrade') {
      // Shown through the first sessions, whatever else happened in them.
      if ((signals.session ?? Number.POSITIVE_INFINITY) > FIRST_GRADE_SESSIONS) continue;
    } else if (!isNew) {
      continue;
    }
    if (isNew && !UNCAPPED_TIPS.has(id) && shownToday(state, signals.today) >= MAX_NEW_TIPS_PER_DAY) continue;
    return id;
  }
  return undefined;
}

/** The state after `id` was shown on `today`: put away, and counted once. */
export function afterShown(state: TipState, id: TipId, today: number): TipState {
  if (state.seen[id] !== undefined) return state;
  const counted = UNCAPPED_TIPS.has(id) ? 0 : 1;
  return {
    ...state,
    seen: { ...state.seen, [id]: today },
    day: today,
    today: shownToday(state, today) + counted,
  };
}

/** A fresh state, settled on `today`. */
export function freshTips(today: number, beginner: boolean): TipState {
  return {
    seen: {},
    day: today,
    today: 0,
    off: false,
    beginner,
    firstDay: today,
    sessions: 0,
    summaries: 0,
    comeback: null,
  };
}

/**
 * Days away that make a return a "welcome back" (M11). Shorter than the
 * daily-limit offer's three, because this is reassurance, not a setting.
 */
export const COMEBACK_LINE_DAYS = 2;

/**
 * Whether Today says "welcome back" (M11): two days or more since the last
 * practice, something due, never beside the daily-limit offer (that one
 * says more and wins), and once per break.
 */
export function wantsComeback(input: {
  today: number;
  lastPractised: number | undefined;
  due: number;
  capOffer: boolean;
  shownFor: number | null;
}): boolean {
  const { today, lastPractised, due, capOffer, shownFor } = input;
  if (lastPractised === undefined || capOffer || due <= 0) return false;
  if (today - lastPractised < COMEBACK_LINE_DAYS) return false;
  return shownFor !== lastPractised;
}

/** "What happens next" on a summary (M4): the full block, one line, or nothing. */
export type NextBlock = 'full' | 'short' | 'none';

/** Summaries that get the full block. */
export const NEXT_FULL_SUMMARIES = 3;

/** Words started below which the one-line version stays. */
export const NEXT_SHORT_WORDS = 50;

/** Which "What happens next" a summary shows, from summaries seen before this one. */
export function nextBlock(summariesBefore: number, wordsStarted: number): NextBlock {
  if (summariesBefore < NEXT_FULL_SUMMARIES) return 'full';
  return wordsStarted < NEXT_SHORT_WORDS ? 'short' : 'none';
}

/** Words listed by name in the full block; above it, two counting lines. */
export const NEXT_WORDS_LISTED = 5;

/**
 * Notebook size below which the next step is another word, not more
 * practice of the same few: "Add another word" on the summary and "Add a
 * word" on Today when nothing is due (M4, M5).
 */
export const SMALL_NOTEBOOK_WORDS = 5;

/** Words before Today offers "By topic or level" (C3): with fewer, there is nothing to cut. */
export const DECKS_TILE_WORDS = 10;
